// Fingerprint is the OCSF "fingerprint" object. The Fingerprint object provides detailed
// information about a fingerprint, which is a compact representation of data used to identify a
// longer piece of information, such as a public key, file content, or application implementation.
// It contains the algorithm or scheme and value of the fingerprint, enabling efficient and
// reliable identification of the associated data.
type Fingerprint struct {
	// The algorithm or scheme used to create the fingerprint, normalized to the caption of
	// algorithm_id . In the case of Other , it is defined by the event source.
	Algorithm string `json:"algorithm,omitempty"`
	// The identifier of the normalized algorithm or scheme, which was used to create the
	// fingerprint.
	AlgorithmID int `json:"algorithm_id"`
	// The encoding of the value attribute, normalized to the caption of encoding_id . In the case
	// of Other , it is defined by the event source.
	Encoding string `json:"encoding,omitempty"`
	// The normalized identifier of the encoding used to represent the fingerprint bytes as the
	// string in value . A verifier must decode value using this encoding to recover the raw hash
	// bytes.
	EncodingID int `json:"encoding_id,omitempty"`
	// The canonical serialization scheme used to produce the deterministic byte sequence that was
	// fingerprinted, normalized to the caption of serialization_id . In the case of Other , it is
	// defined by the event source.
	Serialization string `json:"serialization,omitempty"`
	// The identifier of the normalized canonical serialization scheme used to produce the
	// deterministic byte sequence that was fingerprinted. A verifier must apply the same scheme to
	// reproduce the fingerprinted input. Use Flat where the fingerprinted data is an opaque byte
	// sequence, such as file content, to which no canonical serialization was applied. Distinct
	// from algorithm_id , which identifies how the resulting bytes were hashed.
	SerializationID int `json:"serialization_id,omitempty"`
	// The fingerprint value. Note: This uses type file_hash_t ("Hash"), which has been generalized
	// for all fingerprints but retains the same name and caption for backwards compatibility.
	Value string `json:"value"`
}

