// Observation is the OCSF "observation" object. A record of an observed value or event that
// captures the timing and frequency of its occurrence. Used to track when values/events were first
// detected, last detected, and their total occurrence count.
type Observation struct {
	// Integer representing the total number of times this specific value/event was observed across
	// all occurrences. Helps establish prevalence and patterns.
	Count int `json:"count,omitempty"`
	// The time window when the value or event was first observed. It is used to analyze activity
	// patterns, detect trends, or correlate events within a specific timeframe.
	Timespan *Timespan `json:"timespan,omitempty"`
	// The specific value, event, indicator or data point that was observed and recorded. This is
	// the core piece of information being tracked.
	Value string `json:"value"`
}

// OccurrenceDetails is the OCSF "occurrence_details" object. Details about where in the target
