// Token is the OCSF "token" object. The Token object is the base object for representing tokens,
// API keys, and authentication credentials used across different contexts. This object provides
// common attributes for all token types, including protocol-specific authentication tokens
// (Kerberos, OIDC, SAML) and API/client tokens used for service authentication. When to use this
// object: Use the base token object directly in API activity events to represent API tokens,
// client tokens, or API keys used to authenticate API requests. Examples include: Okta API tokens,
// Microsoft Entra ID Application Registration client secrets, Stripe API keys, AWS API keys. When
// NOT to use this object: Do NOT use the base token object for protocol-specific authentication
// tokens in authentication events - use authentication_token instead (which extends this object).
// Do NOT use token for tracking credential lifecycle and usage patterns - use
// programmatic_credential instead.
type Token struct {
	// The time that the token was created.
	CreatedTime int64 `json:"created_time,omitempty"`
	// The expiration time of the token.
	ExpirationTime int64 `json:"expiration_time,omitempty"`
	// Indicates whether the token is renewable.
	IsRenewable *bool `json:"is_renewable,omitempty"`
	// The last time the token was updated.
	ModifiedTime int64 `json:"modified_time,omitempty"`
	// The human-friendly name of a token or key, if available, such as the name from the Okta API
	// Token API.
	Name string `json:"name,omitempty"`
	// The unique identifier of the tenant or organization that owns the token or key, or the
	// tenant context in which the token is authorized for use. This is particularly relevant in
	// multi-tenant Identity Provider scenarios where tokens are scoped to specific tenants.
	TenantUID string `json:"tenant_uid,omitempty"`
	// The type of the token, normalized to the caption of the type_id value. This indicates
	// whether the token is a Client Token, API Token, or one of the protocol-specific token types.
	Type string `json:"type,omitempty"`
	// The normalized token type identifier. Valid values: 0 (Unknown), 1 (Ticket Granting Ticket -
	// Kerberos), 2 (Service Ticket - Kerberos), 3 (Identity Token - OIDC), 4 (Refresh Token -
	// OIDC), 5 (SAML Assertion), 6 (Client Token - IdP-issued), 7 (API Token - generic API keys),
	// 99 (Other).
	TypeID int `json:"type_id,omitempty"`
	// The unique ID of a token or key, if available, such as the Secret ID of Entra ID Application
	// Registration Client Secrets.
	UID string `json:"uid,omitempty"`
	// The network zone or geographic region that the token or key is authorized to be used from.
	// This may represent network-based access restrictions, geographic limitations, or other
	// zone-based authorization policies. Examples include Okta's network zone restrictions or
	// cloud provider region restrictions.
	Zone string `json:"zone,omitempty"`
}

