// Trace is the OCSF "trace" object. The trace object contains information about a distributed
// trace, which is crucial for observability. Traces are made up of one or more spans, which are
// individual units of work in application activity. Traces track the journey of a request as it
// moves through various services in a system, capturing key details like timing, status, and
// dependencies at each step. Traces provide insights into system performance, helping to identify
// latency, bottlenecks, and issues in complex, distributed environments.
type Trace struct {
	// The total time, in milliseconds, that the trace covers, calculated as the difference between
	// start_time and end_time. This duration helps assess the overall performance of a request as
	// it travels across various services, and is essential for identifying latency and potential
	// bottlenecks within the distributed system. The trace duration may differ from individual
	// span durations due to the propagation and processing times of the trace as it spans multiple
	// components.
	Duration int64 `json:"duration,omitempty"`
	// The end timestamp of the trace, essential for identifying latency and performance
	// bottlenecks. Like the start time, this timestamp is normalized across the trace system to
	// ensure consistency, even when events are recorded across distributed services with
	// unsynchronized clocks. Normalized time allows for accurate trace duration calculations and
	// helps observability tools track overall performance across services, regardless of the
	// individual system time settings.
	EndTime int64 `json:"end_time,omitempty"`
	// The flags associated with the trace, used to indicate specific properties or behaviors, such
	// as whether the trace is sampled or if it has special handling. Flags help control how traces
	// are processed, logged, and analyzed, providing valuable context for tracing and
	// observability tools in identifying trace characteristics or specific tracking requirements.
	Flags []string `json:"flags,omitempty"`
	// Identifies the service or component generating the trace, helping to track and correlate the
	// flow of requests through various parts of a distributed system. This information is
	// essential for understanding the role and performance of specific services within the broader
	// context of system operations and for diagnosing issues across different components.
	Service *Service `json:"service,omitempty"`
	// Represents a single unit of work or operation within a distributed trace. A span typically
	// tracks the execution of a request across a service, capturing important details such as the
	// operation, timestamps, and status. Spans help break down the overall trace into smaller,
	// manageable parts, enabling detailed analysis of the performance and behavior of specific
	// operations within the system. They are crucial for understanding latency, dependencies, and
	// bottlenecks in complex distributed systems.
	Span *Span `json:"span,omitempty"`
	// The start timestamp of the trace, essential for identifying latency and performance
	// bottlenecks. Like the end time, this timestamp is normalized across the trace system to
	// ensure consistency, even when events are recorded across distributed services with
	// unsynchronized clocks. Normalized time enables accurate trace duration calculations and
	// helps observability tools track performance across services, regardless of the individual
	// system time settings.
	StartTime int64 `json:"start_time,omitempty"`
	// The unique identifier of the trace used in distributed systems and microservices
	// architecture to track and correlate requests across various components of an application.
	UID string `json:"uid"`
}

// Trait is the OCSF "trait" object. Describes a characteristic or feature of an entity that was
// observed. For example, this object can be used to represent specific characteristics derived
// from events or findings that can be surfaced as distinguishing traits of the entity in question.
type Trait struct {
	// The high-level grouping or classification this trait belongs to.
	Category string `json:"category,omitempty"`
	// The name of the trait.
	Name string `json:"name,omitempty"`
	// The type of the trait. For example, this can be used to indicate if the trait acts as a
	// contributing factor (increases risk/severity) or a mitigating factor (decreases
	// risk/severity), in the context of the related finding.
	Type string `json:"type,omitempty"`
	// The unique identifier of the trait.
	UID string `json:"uid,omitempty"`
	// The uid attribute in numeric form where applicable. Note: Producers may populate uid_numeric
	// only in addition to uid and not as an alternative to it.
	UIDNumeric int64 `json:"uid_numeric,omitempty"`
	// The values of the trait.
	Values []string `json:"values,omitempty"`
}

// TransformationInfo is the OCSF "transformation_info" object. The transformation_info object
// represents the mapping or transformation used.
type TransformationInfo struct {
	// The transformation language used to transform the data.
	Lang string `json:"lang,omitempty"`
	// The name of the transformation or mapping.
	Name string `json:"name,omitempty"`
	// The product or instance used to make the transformation
	Product *Product `json:"product,omitempty"`
	// Time of the transformation.
	Time int64 `json:"time,omitempty"`
	// The unique identifier of the mapping or transformation.
	UID string `json:"uid,omitempty"`
	// The uid attribute in numeric form where applicable. Note: Producers may populate uid_numeric
	// only in addition to uid and not as an alternative to it.
	UIDNumeric int64 `json:"uid_numeric,omitempty"`
	// The Uniform Resource Locator String where the mapping or transformation exists.
	URLString string `json:"url_string,omitempty"`
}

// TSIG is the OCSF "tsig" object. The TSIG (Transaction Signature) object represents a TSIG
// resource record as defined in RFC 2845. TSIG uses a shared secret key and one-way hash function
// to authenticate DNS messages. Per RFC 2845, at most one TSIG record is permitted per DNS
// message.
type TSIG struct {
	// The HMAC algorithm used to compute the MAC. For example: hmac-sha256 .
	Algorithm string `json:"algorithm,omitempty"`
	// The TSIG error, normalized to the caption of the error_id value. In the case of 'Other', it
	// is defined by the event source.
	Error string `json:"error,omitempty"`
	// The normalized TSIG-specific error code as defined in RFC 2845 and RFC 6895. This is
	// independent of the DNS message header RCODE.
	ErrorID int `json:"error_id,omitempty"`
	// The name of the shared secret key used to sign the DNS message. For example:
	// my-tsig-key.example.com.
	KeyName string `json:"key_name,omitempty"`
}

// TSIGErrorID values for TSIG.ErrorID (TSIG Error ID).
const (
	// No error.
	TSIGErrorIDNoError = 0
	// TSIG signature failure.
	TSIGErrorIDBADSIG = 16
	// Key not recognized.
	TSIGErrorIDBADKEY = 17
	// Signature out of time window.
	TSIGErrorIDBADTIME = 18
	// The TSIG error code is not listed. See the error attribute, which contains a data source
	// specific value.
	TSIGErrorIDOther = 99
)

