// UnmannedSystemOperatingArea is the OCSF "unmanned_system_operating_area" object. The Unmanned
// System Operating Area object describes details about a precise area of operations for a UAS
// flight or mission.
type UnmannedSystemOperatingArea struct {
	// Expressed as either height above takeoff location or height above ground level (AGL) for a
	// UAS current location. This value is provided in meters and must have a minimum resolution of
	// 1 m. Special Values: Invalid , No Value , or Unknown: -1000 m .
	AerialHeight string `json:"aerial_height,omitempty"`
	// Maximum altitude (WGS-84 HAE) for a group or an Intent-Based Network Participant. Measured
	// in meters. Special Values: Invalid , No Value , or Unknown: -1000 m .
	AltitudeCeiling string `json:"altitude_ceiling,omitempty"`
	// Minimum altitude (WGS-84 HAE) for a group or an Intent-Based Network Participant. Measured
	// in meters. Special Values: Invalid , No Value , or Unknown: -1000 m .
	AltitudeFloor string `json:"altitude_floor,omitempty"`
	// The name of the city.
	City string `json:"city,omitempty"`
	// The name of the continent.
	Continent string `json:"continent,omitempty"`
	// A two-element array, containing a longitude/latitude pair. The format conforms with GeoJSON.
	// For example: [-73.983, 40.719] .
	//
	// Deprecated: Use the lat and long attributes instead.
	Coordinates []float64 `json:"coordinates,omitempty"`
	// Indicates the number of UAS in the operating area.
	Count int `json:"count,omitempty"`
	// The ISO 3166-1 Alpha-2 country code. Note: The two letter country code should be
	// capitalized. For example: US or CA .
	Country string `json:"country,omitempty"`
	// The description of the geographical location.
	Desc string `json:"desc,omitempty"`
	// The date and time at which a group or an Intent-Based Network Participant operation ends.
	// (This field is only applicable to Network Remote ID.)
	EndTime int64 `json:"end_time,omitempty"`
	// The aircraft distance above or below the ellipsoid as measured along a line that passes
	// through the aircraft and is normal to the surface of the WGS-84 ellipsoid. This value is
	// provided in meters and must have a minimum resolution of 1 m. Special Values: Invalid , No
	// Value , or Unknown: -1000 m .
	GeodeticAltitude string `json:"geodetic_altitude,omitempty"`
	// Provides quality/containment on geodetic altitude. This is based on ADS-B Geodetic Vertical
	// Accuracy (GVA). Measured in meters.
	GeodeticVerticalAccuracy string `json:"geodetic_vertical_accuracy,omitempty"`
	// Geohash of the geo-coordinates (latitude and longitude). Geohashing is a geocoding system
	// used to encode geographic coordinates in decimal degrees, to a single string.
	Geohash string `json:"geohash,omitempty"`
	// Provides quality/containment on horizontal position. This is based on ADS-B NACp. Measured
	// in meters.
	HorizontalAccuracy string `json:"horizontal_accuracy,omitempty"`
	// Indicates whether the location is on-premises.
	IsOnPremises *bool `json:"is_on_premises,omitempty"`
	// The name of the Internet Service Provider (ISP).
	//
	// Deprecated: Use the network_endpoint.isp or whois.isp attribute according to your use-case.
	Isp string `json:"isp,omitempty"`
	// The geographical Latitude coordinate represented in Decimal Degrees (DD). For example:
	// 42.361145 .
	Lat float64 `json:"lat,omitempty"`
	// A list of Position Location Information (PLI) (latitude/longitude pairs) defining the area
	// where a group or Intent-Based Network Participant operation is taking place. (This field is
	// only applicable to Network Remote ID.)
	Locations []Location `json:"locations,omitempty"`
	// The geographical Longitude coordinate represented in Decimal Degrees (DD). For example:
	// -71.057083 .
	Long float64 `json:"long,omitempty"`
	// The postal code of the location.
	PostalCode string `json:"postal_code,omitempty"`
	// The uncorrected barometric pressure altitude (based on reference standard 29.92 inHg,
	// 1013.25 mb) provides a reference for algorithms that utilize 'altitude deltas' between
	// aircraft. This value is provided in meters and must have a minimum resolution of 1 m..
	// Special Values: Invalid , No Value , or Unknown: -1000 m .
	PressureAltitude string `json:"pressure_altitude,omitempty"`
	// The provider of the geographical location data.
	Provider string `json:"provider,omitempty"`
	// Farthest horizontal distance from the reported location at which any UA in a group may be
	// located (meters). Also allows defining the area where an Intent-Based Network Participant
	// operation is taking place. Default: 0 m.
	Radius string `json:"radius,omitempty"`
	// The alphanumeric code that identifies the principal subdivision (e.g. province or state) of
	// the country. For example, 'CH-VD' for the Canton of Vaud, Switzerland
	Region string `json:"region,omitempty"`
	// The date and time at which a group or an Intent-Based Network Participant operation starts.
	// (This field is only applicable to Network Remote ID.)
	StartTime int64 `json:"start_time,omitempty"`
	// The type of operating area. For example, Takeoff Location , Fixed Location , Dynamic
	// Location .
	Type string `json:"type,omitempty"`
	// The operating area type identifier.
	TypeID int `json:"type_id,omitempty"`
}

