// Vulnerability is the OCSF "vulnerability" object. The vulnerability is an unintended
// characteristic of a computing component or system configuration that multiplies the risk of an
// adverse event or a loss occurring either due to accidental exposure, deliberate attack, or
// conflict with new system components.
type Vulnerability struct {
	// Detail about the security advisory, that is used to publicly disclose cybersecurity
	// vulnerabilities by a vendor.
	Advisory *Advisory `json:"advisory,omitempty"`
	// List of Affected Code objects that describe details about code blocks identified as
	// vulnerable.
	AffectedCode []AffectedCode `json:"affected_code,omitempty"`
	// List of software packages identified as affected by a vulnerability/vulnerabilities.
	AffectedPackages []AffectedPackage `json:"affected_packages,omitempty"`
	// The category of a vulnerability or weakness, as reported by the source tool, such as
	// Container Security or Open Source Security .
	Category string `json:"category,omitempty"`
	// Describes the Common Vulnerabilities and Exposures (CVE) details related to the
	// vulnerability.
	CVE *CVE `json:"cve,omitempty"`
	// Describes the Common Weakness Enumeration (CWE) details related to the vulnerability.
	CWE *CWE `json:"cwe,omitempty"`
	// Information about the chain of dependencies related to the issue as reported by an
	// Application Security or Vulnerability Management tool. E.g., serverless-offline ->
	// @serverless/utils -> memoizee -> es5-ext .
	DependencyChain string `json:"dependency_chain,omitempty"`
	// The description of the vulnerability.
	Desc string `json:"desc,omitempty"`
	// The time when the exploit was most recently observed.
	ExploitLastSeenTime int64 `json:"exploit_last_seen_time,omitempty"`
	// The URL of the exploit code or Proof-of-Concept (PoC).
	ExploitRefURL string `json:"exploit_ref_url,omitempty"`
	// The requirement description related to any constraints around exploit execution.
	ExploitRequirement string `json:"exploit_requirement,omitempty"`
	// The categorization or type of Exploit. E.g., Network or Physical .
	ExploitType string `json:"exploit_type,omitempty"`
	// The time when the vulnerability was first observed.
	FirstSeenTime int64 `json:"first_seen_time,omitempty"`
	// Indicates if a fix is available for the reported vulnerability.
	//
	// Deprecated: Use the is_fix_available attribute instead.
	FixAvailable *bool `json:"fix_available,omitempty"`
	// The fix coverage, normalized to the caption of the fix_coverage_id value.
	FixCoverage string `json:"fix_coverage,omitempty"`
	// The normalized identifier for fix coverage, applicable to this vulnerability. Typically
	// useful, when there are multiple affected packages but only a subset have available fixes.
	FixCoverageID int `json:"fix_coverage_id,omitempty"`
	// Indicates if an exploit or a PoC (proof-of-concept) is available for the reported
	// vulnerability.
	IsExploitAvailable *bool `json:"is_exploit_available,omitempty"`
	// Indicates if a fix is available for the reported vulnerability.
	IsFixAvailable *bool `json:"is_fix_available,omitempty"`
	// A list of KB articles or patches related to an endpoint. A KB Article contains metadata that
	// describes the patch or an update.
	//
	// Deprecated: Use advisory attribute instead.
	KBArticleList []KBArticle `json:"kb_article_list,omitempty"`
	// The KB article/s related to the entity. A KB Article contains metadata that describes the
	// patch or an update.
	//
	// Deprecated: Use the kb_article_list attribute instead.
	KBArticles []string `json:"kb_articles,omitempty"`
	// The time when the vulnerability was most recently observed.
	LastSeenTime int64 `json:"last_seen_time,omitempty"`
	// List of vulnerable packages as identified by the security product
	//
	// Deprecated: Use the affected_packages attribute instead.
	Packages []Package `json:"packages,omitempty"`
	// A list of reference URLs with additional information about the vulnerability.
	References []string `json:"references,omitempty"`
	// List of vulnerability IDs (e.g. CVE ID) that are related to this vulnerability.
	RelatedVulnerabilities []string `json:"related_vulnerabilities,omitempty"`
	// The remediation recommendations on how to mitigate the identified vulnerability.
	Remediation *Remediation `json:"remediation,omitempty"`
	// The vendor assigned severity of the vulnerability.
	Severity string `json:"severity,omitempty"`
	// A title or a brief phrase summarizing the discovered vulnerability.
	Title string `json:"title,omitempty"`
	// The name of the vendor that identified the vulnerability.
	VendorName string `json:"vendor_name,omitempty"`
}

