// WinServiceServiceTypeID values for WinService.ServiceTypeID (Service Type ID).
const (
	// The service type is unknown.
	WinServiceServiceTypeIDUnknown = 0
	// A kernel mode driver.
	WinServiceServiceTypeIDKernelDriver = 1
	// A kernel mode file system minifilter.
	WinServiceServiceTypeIDFileSystemDriver = 2
	// A user mode service that runs in its own process.
	WinServiceServiceTypeIDOwnProcess = 3
	// A user mode service that shares a process with other services.
	WinServiceServiceTypeIDShareProcess = 4
	// The service type is not mapped. See the service_type attribute, which contains an event
	// source specific value.
	WinServiceServiceTypeIDOther = 99
)

// WinServiceServiceTypeIDCaptions maps WinService.ServiceTypeID (Service Type ID) values to their captions.
var WinServiceServiceTypeIDCaptions = map[int]string{
	0:  "Unknown",
	1:  "Kernel Driver",
	2:  "File System Driver",
	3:  "Own Process",
	4:  "Share Process",
	99: "Other",
}
